mapper.select:

where o.member_id=#{memberId}

    and o.status=#{status}

        and latest_after_sale.after_sale_id is null


order by o.create_time desc,o.order_id desc
limit #{limit} offset #{offset}


where o.member_id=#{memberId}
  and (o.status='AFTER_SALE' or latest_after_sale.after_sale_id is not null)
order by o.create_time desc,o.order_id desc
limit #{limit} offset #{offset}
